fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // Iterate through each element in `a` and check if it appears in `b`.
    a.iter().any(|x| b.contains(x))
}

fn slice_contains(s: &[i32], val: i32) -> bool {
    // Use the built‐in `contains` method on slices to test membership.
    s.contains(&val)
}

